from stdlib_primitives import count_target_subseq, kahan_max_subarray

def bidirectional_subseq_score(text: str, pat: str, gains: list[float]) -> float:
    fwd = count_target_subseq(text, pat)
    rev = count_target_subseq(text[::-1], pat[::-1])
    return (fwd + rev) * kahan_max_subarray(gains)

